    items: Vec<T>,
}

impl<T> Stack<T> {
    pub fn new() -> Self {
        Stack { items: Vec::new() }
    }

    pub fn push(&mut self, item: T) {
        self.items.push(item);
    }

    pub fn pop(&mut self) -> Option<T> {
        if !self.items.is_empty() {
            Some(self.items.remove(self.items.len() - 1))
        } else {
            None
        }
    }

    pub fn len(&self) -> usize {
        self.items.len()
    }

