/// Returns Some(index) if target is in the (sorted ascending) slice, else None.
pub fn binary_search(arr: &[i32], target: i32) -> Option<usize> {
    let mut lo: usize = 0;
    let mut hi: usize = arr.len();
    while lo < hi {
        let mid = (lo + hi) / 2;
        if arr[mid] < target {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    if lo < arr.len() && arr[lo] == target {
        Some(lo)
    } else {
        None
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn it_searches() {
        let v: Vec<i32> = vec![1, 3, 5, 7, 9, 11];
        assert_eq!(binary_search(&v, 1), Some(0));
        assert_eq!(binary_search(&v, 11), Some(5));
        assert_eq!(binary_search(&v, 7), Some(3));
        assert_eq!(binary_search(&v, 4), None);
        assert_eq!(binary_search(&v, 12), None);
        assert_eq!(binary_search(&[], 5), None);
    }

    #[test]
    fn test_edge_cases() {
        // Test cases where the target is at the start, end, or middle of the array
        assert_eq!(binary_search(&vec![10], 10), Some(0));
        assert_eq!(binary_search(&vec![1, 2, 3, 4, 5], 5), Some(4));
        assert_eq!(binary_search(&vec![1, 2, 3, 4, 5], 1), Some(0));
        assert_eq!(binary_search(&vec![1, 2, 3, 4, 5], 3), Some(2));

        // Test cases where the array is empty
        assert_eq!(binary_search::<i32>(&Vec::new(), 10), None);

        // Test cases where the target is not present and the loop exits without finding it
        assert_eq!(binary_search(&vec![1, 3, 5, 7, 9], 6), None);
        assert_eq!(binary_search(&vec![1, 3, 5, 7, 9], 8), None);
        assert_eq!(binary_search(&vec![1, 3, 5, 7, 9], 2), None);
        assert_eq!(binary_search(&vec![1, 3, 5, 7, 9], 0), None);
    }
}
